CREATE TABLE devices (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,public_key TEXT NOT NULL,fingerprint TEXT NOT NULL,secret_hash TEXT NOT NULL,label_ciphertext BLOB NOT NULL DEFAULT x'',platform TEXT NOT NULL DEFAULT 'unknown',created_at TEXT NOT NULL,last_seen_at TEXT NOT NULL DEFAULT '',revoked_at TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX idx_devices_user_fingerprint ON devices(user_id,fingerprint);
CREATE TABLE memberships (id TEXT PRIMARY KEY,container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL,created_at TEXT NOT NULL,revoked_at TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX idx_memberships_container_user ON memberships(container_id,user_id);
CREATE TABLE pairing_nonces (nonce TEXT PRIMARY KEY,purpose TEXT NOT NULL,user_id TEXT NOT NULL,used_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE key_envelopes (id TEXT PRIMARY KEY,container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE,device_id TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE,key_generation INTEGER NOT NULL,alg TEXT NOT NULL,envelope BLOB NOT NULL,created_at TEXT NOT NULL);
CREATE UNIQUE INDEX idx_envelopes_container_device_gen ON key_envelopes(container_id,device_id,key_generation);
CREATE TABLE device_containers (device_id TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE,container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE,selected_at TEXT NOT NULL,PRIMARY KEY(device_id,container_id));
CREATE TABLE conflicts (id TEXT PRIMARY KEY,object_id TEXT NOT NULL REFERENCES objects(id) ON DELETE CASCADE,container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE,base_version INTEGER NOT NULL,current_version INTEGER NOT NULL,blob_digest TEXT NOT NULL REFERENCES blobs(digest),ciphertext_bytes INTEGER NOT NULL,key_generation INTEGER NOT NULL,device_id TEXT NOT NULL DEFAULT '',change_seq INTEGER NOT NULL,created_at TEXT NOT NULL,resolved_at TEXT NOT NULL DEFAULT '');
CREATE TABLE attachments (id TEXT PRIMARY KEY,container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE,blob_digest TEXT NOT NULL REFERENCES blobs(digest),preview_digest TEXT NOT NULL DEFAULT '',ciphertext_bytes INTEGER NOT NULL,metadata_ciphertext BLOB NOT NULL,key_generation INTEGER NOT NULL,change_seq INTEGER NOT NULL,created_at TEXT NOT NULL,deleted_at TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX idx_attachments_container_digest ON attachments(container_id,blob_digest);
CREATE TABLE upload_sessions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE,kind TEXT NOT NULL DEFAULT 'attachment',declared_bytes INTEGER NOT NULL,chunk_bytes INTEGER NOT NULL,expected_digest TEXT NOT NULL DEFAULT '',received_bytes INTEGER NOT NULL DEFAULT 0,next_chunk INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,expires_at TEXT NOT NULL,finalized_at TEXT NOT NULL DEFAULT '');
CREATE TABLE idempotency (key_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,route TEXT NOT NULL,status INTEGER NOT NULL,resource_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE audit_events (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,event TEXT NOT NULL,container_id TEXT NOT NULL DEFAULT '',object_id TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
